export const ANLEITUNG_CSS = "\n.anleitung {\n  --anl-bg: var(--background); --anl-card: var(--card); --anl-text: var(--foreground); --anl-muted: var(--muted);\n  --anl-border: var(--border); --anl-accent: var(--accent); --anl-on-accent: var(--accent-foreground);\n  --anl-accent-soft: color-mix(in srgb, var(--accent) 12%, transparent);\n  --anl-warn-bg: var(--warnung-flaeche); --anl-warn-border: var(--warnung-rand); --anl-warn-text: var(--warnung);\n  --anl-tip-bg: var(--ok-flaeche); --anl-tip-border: var(--ok-rand);\n  --anl-hero: var(--accent); --anl-on-hero: var(--accent-foreground);\n}\n\n.anleitung, .anleitung * { box-sizing: border-box; }\n.anleitung { scroll-behavior: smooth; scroll-padding-top: 16px; }\n.anleitung { margin: 0; background: var(--anl-bg); color: var(--anl-text); font: 16px/1.6 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; }\n.anleitung a { color: var(--anl-accent); }\n.anleitung .layout { display: grid; grid-template-columns: 270px minmax(0, 1fr); max-width: 1320px; margin: 0 auto; }\n.anleitung nav.toc { position: sticky; top: env(safe-area-inset-top, 0px); height: 100vh; overflow-y: auto; padding: 28px 18px 28px 24px; border-right: 1px solid var(--anl-border); }\n.anleitung nav.toc .marke { display: flex; align-items: center; gap: 10px; font-weight: 650; font-size: 18px; margin-bottom: 18px; color: var(--anl-text); text-decoration: none; }\n.anleitung nav.toc ol { list-style: none; margin: 0; padding: 0; counter-reset: k; }\n.anleitung nav.toc li { counter-increment: k; }\n.anleitung nav.toc li a { display: block; padding: 5px 10px; border-radius: 8px; color: var(--anl-muted); text-decoration: none; font-size: 14.5px; }\n.anleitung nav.toc li a::before { content: counter(k) \". \"; color: var(--anl-accent); font-weight: 600; }\n.anleitung nav.toc li a:hover { background: var(--anl-accent-soft); color: var(--anl-text); }\n.anleitung .inhalt { padding: 32px 40px 80px; min-width: 0; }\n.anleitung header.titel { background: var(--anl-hero); color: var(--anl-on-hero); border-radius: 16px; padding: 34px 36px; margin-bottom: 36px; }\n.anleitung header.titel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.2; }\n.anleitung header.titel p { margin: 0; opacity: .92; max-width: 720px; }\n.anleitung section { background: var(--anl-card); border: 1px solid var(--anl-border); border-radius: 16px; padding: 28px 32px; margin-bottom: 28px; }\n.anleitung h2 { margin: 0 0 12px; font-size: 25px; line-height: 1.25; }\n.anleitung h2 .nr { color: var(--anl-accent); margin-right: 6px; }\n.anleitung h3 { margin: 28px 0 8px; font-size: 19px; }\n.anleitung p { margin: 0 0 12px; max-width: 78ch; }\n.anleitung ul, .anleitung ol { padding-left: 22px; margin: 0 0 12px; max-width: 76ch; }\n.anleitung li { margin-bottom: 4px; }\n.anleitung figure { margin: 18px 0 22px; }\n.anleitung figure img { display: block; width: 100%; max-width: 100%; height: auto; border: 1px solid var(--anl-border); border-radius: 10px; background: #fff; }\n.anleitung figure.schmal img { max-width: 560px; }\n.anleitung figure.handy img { max-width: 300px; border-radius: 18px; }\n.anleitung figcaption { font-size: 13.5px; color: var(--anl-muted); margin-top: 8px; max-width: 78ch; }\n.anleitung .nebeneinander { display: flex; flex-wrap: wrap; gap: 18px; align-items: flex-start; }\n.anleitung .nebeneinander figure { margin: 10px 0; }\n.anleitung .nebeneinander figure.handy { flex: 0 1 300px; }\n.anleitung .nebeneinander figure.breit { flex: 1 1 520px; min-width: 0; }\n.anleitung .hinweis, .anleitung .tipp { border-radius: 10px; padding: 12px 16px; margin: 14px 0; font-size: 15px; max-width: 80ch; }\n.anleitung .hinweis { background: var(--anl-warn-bg); border: 1px solid var(--anl-warn-border); color: var(--anl-warn-text); }\n.anleitung .tipp { background: var(--anl-tip-bg); border: 1px solid var(--anl-tip-border); }\n.anleitung .hinweis strong, .anleitung .tipp strong { display: block; margin-bottom: 2px; }\n.anleitung .schritte { counter-reset: s; list-style: none; padding: 0; }\n.anleitung .schritte > li { counter-increment: s; position: relative; padding-left: 40px; margin-bottom: 10px; }\n.anleitung .schritte > li::before { content: counter(s); position: absolute; left: 0; top: 0; width: 28px; height: 28px; border-radius: 50%; background: var(--anl-accent); color: var(--anl-on-accent); font-weight: 650; font-size: 14px; display: flex; align-items: center; justify-content: center; }\n.anleitung kbd, .anleitung .knopf { display: inline-block; font: 600 13px/1.4 system-ui, sans-serif; padding: 1px 8px; border: 1px solid var(--anl-border); border-radius: 6px; background: var(--anl-bg); white-space: nowrap; }\n.anleitung table { border-collapse: collapse; width: 100%; max-width: 820px; font-size: 15px; margin: 8px 0 14px; }\n.anleitung th, .anleitung td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--anl-border); vertical-align: top; }\n.anleitung th { color: var(--anl-muted); font-weight: 600; font-size: 13.5px; }\n.anleitung .zurueck { font-size: 13px; text-decoration: none; }\n@media (max-width: 1279px) {\n  .anleitung .layout { display: block; }\n  .anleitung nav.toc { position: static; height: auto; border-right: 0; border-bottom: 1px solid var(--anl-border); padding: 20px 16px; }\n  .anleitung nav.toc ol { columns: 2; column-gap: 12px; }\n  .anleitung .inhalt { padding: 20px 16px 60px; }\n  .anleitung section { padding: 20px 18px; border-radius: 12px; }\n  .anleitung header.titel { padding: 24px 20px; border-radius: 12px; }\n  .anleitung header.titel h1 { font-size: 26px; }\n  .anleitung figure.handy img { max-width: 100%; }\n}\n@media (max-width: 520px) { .anleitung nav.toc ol { columns: 1; } }\n@media print {\n  .anleitung nav.toc { display: none; } .anleitung .layout { display: block; } .anleitung section { break-inside: auto; border: 0; padding: 0; }\n  .anleitung figure { break-inside: avoid; }\n}\n\n.anleitung { font: inherit; font-size: 16px; line-height: 1.6; background: transparent; }\n.anleitung .layout { max-width: none; }\n.anleitung nav.toc { padding: 4px 16px 24px 0; height: 100dvh; }\n.anleitung nav.toc .marke { display: none; }\n.anleitung .inhalt { padding: 0 0 40px 24px; }\n@media (max-width: 1279px) {\n  /* Schmaler: Inhaltsverzeichnis als Reihe kleiner Sprungmarken über dem Text. */\n  .anleitung nav.toc { padding: 0 0 16px; height: auto; margin-bottom: 20px; }\n  .anleitung nav.toc ol { columns: auto; display: flex; flex-wrap: wrap; gap: 6px; }\n  .anleitung nav.toc li { margin: 0; }\n  .anleitung nav.toc li a { border: 1px solid var(--rand-ruhig); padding: 4px 10px; font-size: 13.5px; border-radius: 999px; }\n  .anleitung .inhalt { padding: 0; }\n}\n";

export const ANLEITUNG_HTML = "<div class=\"layout\">\n<nav class=\"toc\" aria-label=\"Inhalt\">\n  <a class=\"marke\" href=\"#start\">\n    <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" style=\"color:var(--accent)\"><path d=\"M12 2.5 20.2 7.25v9.5L12 21.5 3.8 16.75v-9.5Z\"/><path d=\"M7.5 12.5c2.5-3 6.5-3 9 0M7.5 12.5c2.5 2 6.5 2 9 0\"/></svg>\n    Imkereiverwaltung\n  </a>\n  <ol>\n    <li><a href=\"#zugang\">Zugang einrichten</a></li>\n    <li><a href=\"#aufbau\">Aufbau der App</a></li>\n    <li><a href=\"#beispiel\">Beispielstand &amp; erste Schritte</a></li>\n    <li><a href=\"#staende\">Bienenstände</a></li>\n    <li><a href=\"#voelker\">Völker</a></li>\n    <li><a href=\"#stockkarte\">Durchsicht erfassen</a></li>\n    <li><a href=\"#massnahmen\">Maßnahmen &amp; Kalender</a></li>\n    <li><a href=\"#koeniginnen\">Königinnen</a></li>\n    <li><a href=\"#zucht\">Zucht</a></li>\n    <li><a href=\"#behandlungen\">Behandlungen</a></li>\n    <li><a href=\"#dokumente\">Dokumente</a></li>\n    <li><a href=\"#lager\">Lager</a></li>\n    <li><a href=\"#qr\">QR-Codes &amp; Scannen</a></li>\n    <li><a href=\"#velutina\">Velutina</a></li>\n    <li><a href=\"#einstellungen\">Einstellungen</a></li>\n    <li><a href=\"#fragen\">Tipps &amp; Fragen</a></li>\n  </ol>\n</nav>\n\n<div class=\"inhalt\" id=\"start\">\n<header class=\"titel\">\n  <h1>Anleitung zur Imkereiverwaltung</h1>\n  <p>Die Imkereiverwaltung ist deine digitale Stockkarte: Bienenstände, Völker, Durchsichten, Königinnen, Zucht, Behandlungen und Lager an einem Ort, am Rechner genauso wie am Handy direkt am Bienenstand. Diese Anleitung führt dich vom ersten Anmelden bis zur fertigen Stockkarte.</p>\n</header>\n\n<div class=\"hinweis\">\n  <strong>Zu den Bildern in dieser Anleitung</strong>\n  Die Bilder zeigen einen erfundenen Beispielstand „Obstwiese“ mit drei Völkern. Der Kartenhintergrund ist in den Bildern ausgeblendet, in der App siehst du dort die echte Karte bzw. das Satellitenbild. Die App wird laufend weiterentwickelt, Einzelheiten können deshalb leicht anders aussehen. Stand dieser Anleitung: 30. Oktober 2026.\n</div>\n\n\n<!-- 1 -->\n<section id=\"zugang\">\n<h2><span class=\"nr\">1</span>Einrichten und anmelden</h2>\n<p>Die Imkereiverwaltung läuft auf deinem eigenen Server. Deine Daten liegen nur dort. Wie du die App installierst, steht in der <a href=\"https://github.com/frawoer79/Imkerei_Verwaltung/blob/main/installation/LIESMICH.md\">Installationsanleitung</a>. Am Ende zeigt das Installationsskript einen <strong>Einrichtungscode</strong>.</p>\n<h3>Erster Start: der Einrichtungsassistent</h3>\n<ol class=\"schritte\">\n  <li>Öffne die Adresse deiner App im Browser. Beim ersten Mal kommt der Einrichtungsassistent.</li>\n  <li>Gib den <strong>Einrichtungscode</strong> ein. Er steht auch in der Datei <code>.env</code> auf dem Server.</li>\n  <li>Trag <strong>deinen Namen</strong> ein (steht z.&nbsp;B. im Bestandsbuch) und auf Wunsch den <strong>Namen der Imkerei</strong> (steht oben im Menü) und dein <strong>Bundesland</strong>.</li>\n  <li>Wähle <strong>Benutzername</strong> und <strong>Passwort</strong>. Damit meldest du dich künftig an. Dieser Zugang ist der Hauptzugang: Er darf alles, auch Helfer anlegen und Updates einspielen.</li>\n  <li>Lass den Haken bei <em>Täglich nach Updates suchen</em> gesetzt, dann meldet die App neue Versionen selbst. Tippe auf <span class=\"knopf\">Einrichten</span>.</li>\n</ol>\n<h3>Helfer einladen</h3>\n<p>Arbeiten Familie oder Mitimker mit, bekommen sie eigene Zugänge zu deinen Daten. Unter <em>Einstellungen → Helfer</em> legst du sie an:</p>\n<ol class=\"schritte\">\n  <li><strong>Name</strong> und <strong>Rechte</strong> wählen: <em>Lesen und schreiben</em> oder <em>Nur lesen</em>.</li>\n  <li>Ein <strong>Startpasswort</strong> vergeben. Gib es auf anderem Weg weiter, etwa mündlich. Beim ersten Anmelden muss der Helfer ein eigenes Passwort wählen.</li>\n  <li>Auf Wunsch eine <strong>E-Mail</strong> eintragen. Dorthin schickt die App den Link zur App (nie ein Passwort), und der Helfer kann damit selbst ein neues Passwort anfordern. Das klappt, sobald der <a href=\"#einstellungen\">E-Mail-Versand</a> eingerichtet ist.</li>\n</ol>\n<p>Rechte ändern, Passwort zurücksetzen oder einen Helfer sperren geht jederzeit in derselben Liste. Unter <em>Einstellungen → Historie</em> siehst du, wer was angelegt oder geändert hat.</p>\n<h3>Später wieder anmelden</h3>\n<p>Öffne die Adresse der App und melde dich mit Namen und Passwort an. Du bleibst danach 30 Tage angemeldet.</p>\n<figure class=\"schmal\"><img src=\"/anleitung/bilder/login-desktop.webp\" loading=\"lazy\" alt=\"Anmeldeseite\"><figcaption>Die Anmeldeseite.</figcaption></figure>\n<p><strong>Passwort vergessen?</strong> Helfer mit hinterlegter E-Mail tippen auf der Anmeldeseite auf <em>Passwort vergessen</em> und bekommen einen Link, der eine Stunde gilt. Sonst setzt der Hauptzugang unter <em>Einstellungen → Helfer</em> ein neues Startpasswort. Für den Hauptzugang selbst gibt es einen Befehl auf dem Server, siehe <a href=\"https://github.com/frawoer79/Imkerei_Verwaltung/blob/main/installation/LIESMICH.md\">Installationsanleitung</a>.</p>\n<div class=\"tipp\">\n  <strong>Tipp: Auf den Home-Bildschirm legen</strong>\n  Am iPhone/iPad in Safari auf <em>Teilen</em> und dann <em>Zum Home-Bildschirm</em> tippen (Android/Chrome: Menü, <em>Zum Startbildschirm hinzufügen</em>). Dann startet die Imkereiverwaltung wie eine App ohne Adressleiste, und das Handy kann sich Name und Passwort merken.\n</div>\n<h3>Du hast einen Testzugang bekommen?</h3>\n<p>Manche Betreiber laden Tester per persönlichem Einladungslink ein. Er gilt genau einmal. Öffne ihn, wähle Namen und Passwort, lies den Hinweis zur Testversion und tippe auf <span class=\"knopf\">Zugang einrichten</span>. Dabei entsteht deine eigene Datenablage mit dem Beispielstand „Obstwiese“. Niemand sonst sieht deine Daten, aber es gibt keine Garantie für sie. Merk dir danach die Adresse der App, der Einladungslink funktioniert kein zweites Mal.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/einladung-handy.webp\" loading=\"lazy\" alt=\"Einladungsseite mit Feldern für Name und Passwort\"><figcaption>Die Einladungsseite am Handy.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/willkommen-handy.webp\" loading=\"lazy\" alt=\"Willkommensseite mit Adresse der App und Hinweis auf den Beispielstand\"><figcaption>Nach dem Einrichten: Adresse merken, dann Anleitung lesen oder gleich loslegen.</figcaption></figure>\n</div>\n</section>\n\n<!-- 2 -->\n<section id=\"aufbau\">\n<h2><span class=\"nr\">2</span>Aufbau der App</h2>\n<p>Wie das Menü aussieht, hängt vom gewählten <a href=\"#einstellungen\">Design</a> ab. Im Design <em>Wiese</em> (Vorgabe) steht es am Rechner links, am Handy oben als Kachelraster. Im Design <em>Wald</em> liegt es am Handy als Leiste unten, mit <em>Scannen</em> in der Mitte und den übrigen Bereichen unter <em>Mehr</em>. Im Design <em>Bergsee</em> ist es ein dunkles Band oben, am Handy eine Reihe Reiter. <em>Einstellungen</em> und <em>Anleitung</em> stehen in allen Designs etwas kleiner und abgesetzt unter dem Hauptmenü. Die Bereiche sind überall dieselben:</p>\n<table>\n  <tr><th>Bereich</th><th>Wofür</th></tr>\n  <tr><td><strong>Bienenstände</strong></td><td>Startseite: deine Stände mit den Völkern darin, von dort geht es zur Stockkarte jedes Volkes. Oben sucht das Feld <em>Volk suchen</em> über alle Stände nach Name oder Nummer.</td></tr>\n  <tr><td><strong>Scannen</strong></td><td>QR-Code an der Beute scannen und direkt die richtige Stockkarte öffnen.</td></tr>\n  <tr><td><strong>Maßnahmen</strong></td><td>Alles, was zu tun ist, über alle Völker hinweg, als Liste und als Monatskalender. Die rote Zahl zeigt, was heute fällig oder überfällig ist.</td></tr>\n  <tr><td><strong>Königinnen</strong></td><td>Bestand mit Abstammung (Mutter- und Vaterseite), Begattung, Lebenslauf und Bewertung, dazu die Zuchtplanung.</td></tr>\n  <tr><td><strong>Behandlungen</strong></td><td>Bestandsbuch für Tierarzneimittel, mit Nachweis als PDF. Dazu Verfahren ohne Medikament wie TBE oder Bannwabe, mit Fahrplan.</td></tr>\n  <tr><td><strong>Dokumente</strong></td><td>Rechnungen, Gesundheitszeugnisse usw., auf Wunsch mit Stand, Volk oder Königin verknüpft und per E-Mail versendbar.</td></tr>\n  <tr><td><strong>Lager</strong></td><td>Material (Zargen, Klimadeckel, Mittelwände, Futter) und Erzeugnisse (Honig, Wachs …), auf Wunsch mit Warenwert. Bestandslisten und Buchungen als PDF.</td></tr>\n  <tr><td><strong>Velutina</strong></td><td>Meldungen der Asiatischen Hornisse rund um deine Stände (nur Baden-Württemberg) und die Nestsuche per Locktopf.</td></tr>\n  <tr><td><strong>Einstellungen</strong></td><td>Deine Angaben als Bienenhalter, welche Bereiche du nutzt, Design, E-Mail, Beutensysteme, Belegstellen, Lager (Sorten, Gebinde, Preise, Lagerorte), QR-Codes, Kalender-Abo, Helfer, Historie, Updates.</td></tr>\n  <tr><td><strong>Anleitung</strong></td><td>Diese Anleitung.</td></tr>\n</table>\n<p>Brauchst du einen Bereich nicht, etwa Zucht oder Lager, blendest du ihn unter <em>Einstellungen → Bereiche</em> aus (siehe <a href=\"#einstellungen\">Einstellungen</a>).</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/start.webp\" loading=\"lazy\" alt=\"Startseite am Rechner mit Menü links\"><figcaption>Am Rechner: Menü links, unten der Hell/Dunkel-Schalter und <em>Abmelden</em>. Das gelbe Abzeichen erscheint nur in Testzugängen. Alle Bilder zeigen das Design Wiese.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-start.webp\" loading=\"lazy\" alt=\"Startseite am Handy mit Kachelmenü oben\"><figcaption>Am Handy: Menü oben als Kacheln.</figcaption></figure>\n</div>\n<p>Über jeder Seitenüberschrift steht eine Zeile mit <span class=\"knopf\">← Zurück</span> und dem Pfad, z.&nbsp;B. „Bienenstände › Obstwiese“. <em>Zurück</em> führt auf die Seite, von der du gekommen bist, ein Tipp auf den Pfad springt direkt dorthin. Mit dem Schalter neben der Sonne wechselst du zwischen heller und dunkler Darstellung. Neben dem Logo steht „Imkereiverwaltung“. Einen eigenen Namen, etwa den deiner Imkerei, trägst du unter <em>Einstellungen → Bienenhalter</em> bei <em>Name im Menü</em> ein.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-volk-dunkel.webp\" loading=\"lazy\" alt=\"Volk-Seite in dunkler Darstellung\"><figcaption>Dunkle Darstellung am Handy.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-massnahmen-dunkel.webp\" loading=\"lazy\" alt=\"Maßnahmen in dunkler Darstellung\"><figcaption>Maßnahmen, dunkel.</figcaption></figure>\n</div>\n</section>\n\n<!-- 3 -->\n<section id=\"beispiel\">\n<h2><span class=\"nr\">3</span>Deine ersten Schritte</h2>\n<p>Nach dem Einrichten ist die App leer. Am schnellsten kommst du so zu deiner ersten eigenen Stockkarte:</p>\n<ol class=\"schritte\">\n  <li><strong>Einstellungen → Bienenhalter:</strong> Name, Anschrift und Bundesland prüfen. Das steht später im Kopf des Behandlungsnachweises, und am Bundesland erkennt die App, ob sie dir die Hornissen-Meldungen aus Baden-Württemberg zeigt.</li>\n  <li><strong>Einstellungen → Beutensysteme:</strong> dein System hinzufügen, z.&nbsp;B. Zander oder Deutsch Normalmaß (siehe unten). Sonst kannst du beim Volk keinen passenden Brutraum wählen.</li>\n  <li><strong>Bienenstände → Neuer Bienenstand:</strong> deinen ersten Stand anlegen.</li>\n  <li><strong>Im Stand → Neues Volk:</strong> die Völker anlegen.</li>\n  <li><strong>Im Volk → Durchsicht erfassen:</strong> die erste Durchsicht festhalten.</li>\n</ol>\n<p>Königinnen, Belegstellen, Medikamente und Lager kannst du später nach Bedarf ergänzen.</p>\n<h3>Der Beispielstand in den Bildern</h3>\n<p>Die Bilder dieser Anleitung zeigen den erfundenen Stand <strong>„Obstwiese“</strong> mit drei Völkern und einer Saison Geschichte. Testzugänge bekommen ihn mit. An ihm siehst du, wie die Teile zusammenhängen:</p>\n<ul>\n  <li><strong>Volk 1</strong> ist das starke, sanfte Wirtschaftsvolk. Seine Königin trägt den gelben Stern, zwei Honigernten stehen im Verlauf und im Lager.</li>\n  <li><strong>Volk 2</strong> ging im Mai in Schwarmstimmung. Daraus entstand ein Ableger, die Nachschau steht als erledigte Maßnahme im Verlauf.</li>\n  <li><strong>Volk 3</strong> ist dieser Ableger. Seine Königin hat es selbst nachgezogen, sie stammt laut Abstammung von der Königin aus Volk 2. Im Juli lag Varroa über der Schadschwelle, danach folgt die Ameisensäure-Behandlung aller drei Völker. Der Fütterer liegt noch drauf, und eine Futterkontrolle ist überfällig.</li>\n</ul>\n<p>Hast du einen Testzugang, darfst du am Beispielstand alles ändern, ergänzen oder löschen. Brauchst du ihn nicht mehr, archivierst du ihn (Stand öffnen, <em>bearbeiten</em>, <em>Archivieren</em>). Die Beispielbehandlung bleibt dabei im Bestandsbuch stehen; solange sie existiert, lässt sich der Stand nur archivieren, nicht endgültig löschen.</p>\n\n<h3>Beutensystem hinzufügen</h3>\n<p>Unter <em>Einstellungen → Beutensysteme</em> tippst du auf dein System, etwa <span class=\"knopf\">+ Deutsch Normalmaß</span>. Die genormten Rähmchenmaße und Zargen kommen gleich mit, samt einem Richtwert, wie viel Honig eine volle Zarge ungefähr bringt. Klappst du ein System auf, kannst du Wabenzahl und Honigmenge an deine Erfahrung anpassen. Ein System, das nicht in der Liste steht, legst du über <em>Eigenes System anlegen</em> an.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/beuten-leer.webp\" loading=\"lazy\" alt=\"Auswahl der gängigen Beutensysteme\"><figcaption>Auswahl der gängigen Systeme.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/beuten-zander.webp\" loading=\"lazy\" alt=\"Zander aufgeklappt mit Zargen\"><figcaption>Zander aufgeklappt: die Zargen mit Wabenzahl und Honig-Richtwert.</figcaption></figure>\n</div>\n</section>\n\n<!-- 4 -->\n<section id=\"staende\">\n<h2><span class=\"nr\">4</span>Bienenstände</h2>\n<h3>Stand anlegen</h3>\n<p>Auf der Startseite <span class=\"knopf\">+ Neuer Bienenstand</span>. Gib einen Namen ein und wähle die Art:</p>\n<ul>\n  <li><strong>Fester Stand:</strong> dort wird auch überwintert. Auf allen Karten blauer Pin.</li>\n  <li><strong>Wanderstand:</strong> Völker stehen nur vorübergehend dort, z.&nbsp;B. für eine Tracht oder als Ableger. Auf allen Karten gelber Pin.</li>\n</ul>\n<p>Den Standort setzt du auf zwei gleichwertigen Wegen: Adresse eintippen und <span class=\"knopf\">Auf Karte suchen</span>, oder direkt in die Karte tippen bzw. den Punkt verschieben. Beides füllt das jeweils andere automatisch aus. Mit <em>Satellit</em> und <em>Hybrid</em> (Luftbild mit Straßen und Ortsnamen) wechselst du die Ansicht, <em>Vollbild</em> hilft am Handy beim genauen Setzen. Ein Foto des Standorts ist optional und erscheint später als Bild auf der Kachel.</p>\n<figure><img src=\"/anleitung/bilder/stand-neu.webp\" loading=\"lazy\" alt=\"Formular Neuer Bienenstand\"><figcaption>Neuer Bienenstand (Kartenhintergrund in der Anleitung ausgeblendet).</figcaption></figure>\n\n<h3>Die Übersicht</h3>\n<p>Jeder Stand ist eine Kachel mit Art, Ort, Zahl der Völker und Datum der letzten Durchsicht. Die Zahl oben an der Kachel zählt Maßnahmen: <strong>rot</strong> mit Warnzeichen, wenn dort etwas überfällig oder heute fällig ist, sonst unauffällig grau mit allen offenen. Eine Maßnahme für mehrere Völker zählt dabei einmal. Ein Tipp auf die Kachel öffnet den Stand. Über <span class=\"knopf\">Kartenübersicht</span> siehst du alle Stände auf einer Karte, mit Flugradius und einer kleinen Legende unten links.</p>\n<figure><img src=\"/anleitung/bilder/karte.webp\" loading=\"lazy\" alt=\"Kartenübersicht mit Stand und Flugradius\"><figcaption>Kartenübersicht mit Flugradius, oben einstellbar. Die Einstellung merkt sich jedes Gerät.</figcaption></figure>\n\n<h3>Die Seite eines Stands</h3>\n<p>Oben stehen Name, Art, Ort und Notizen. Darunter links der Kasten <strong>Asiatische Hornisse</strong> (siehe <a href=\"#velutina\">Velutina</a>), rechts eine kleine Kartenvorschau. Die Vorschau lässt sich nicht verschieben, ein Tipp darauf öffnet die Kartenübersicht. Am Handy stehen die Völker zuerst, Karte und Hornissen-Kasten weiter unten.</p>\n<p>Die Knöpfe <span class=\"knopf\">Durchsicht erfassen</span> und <span class=\"knopf\">Maßnahme</span> halten etwas für mehrere Völker dieses Stands auf einmal fest (siehe <a href=\"#sammel\">Mehrere Völker auf einmal</a>). Darunter folgen die <strong>Völker als Kacheln</strong>. Jede Kachel zeigt:</p>\n<ul>\n  <li>Zeichenfarbe der Königin als Punkt, Name, Rasse, bei herausragenden Königinnen den Stern;</li>\n  <li>Plaketten: Status, <strong>Gesamteindruck</strong> der letzten Durchsicht in Ampelfarbe, <em>Fütterer drauf</em>, solange ein Fütterer aufliegt;</li>\n  <li>den Kasten <strong>Wertung letzte Durchsicht</strong>: alle Bewertungen der letzten Durchsicht als Text, grün, gelb oder rot gefärbt;</li>\n  <li>die offenen Maßnahmen mit Termin. Der Kasten wird rot, wenn etwas überfällig ist, gelb bei „heute fällig“, sonst bleibt er ruhig.</li>\n</ul>\n<ul>\n  <li><strong>Sortierung:</strong> <em>Chronologisch</em> (Reihenfolge der Anlage) oder <em>Standposition</em>. Bei Standposition schiebst du die Kacheln mit den Pfeilen so, wie die Beuten wirklich nebeneinander stehen.</li>\n  <li><strong>bearbeiten</strong> neben dem Standnamen: Angaben, Standort und Foto ändern, Stand archivieren.</li>\n  <li>Ganz unten: <strong>Dokumente</strong> zu diesem Stand.</li>\n</ul>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/stand.webp\" loading=\"lazy\" alt=\"Seite des Bienenstands Obstwiese\"><figcaption>Stand „Obstwiese“: Bei Volk 3 ist die Futterkontrolle überfällig, deshalb ist sein Maßnahmen-Kasten rot. Der Fütterer liegt noch drauf.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-stand.webp\" loading=\"lazy\" alt=\"Bienenstand am Handy\"><figcaption>Derselbe Stand am Handy.</figcaption></figure>\n</div>\n<div class=\"tipp\">\n  <strong>Archivieren statt löschen</strong>\n  Ein Stand (oder ein Volk), den du nicht mehr brauchst, wird archiviert: Er verschwindet aus den Übersichten, bleibt aber mit allen Stockkarten und Fotos erhalten und lässt sich wiederherstellen. Archivierte Stände findest du unten auf der Startseite. Endgültiges Löschen ist ein eigener Schritt, bei dem du zur Sicherheit den Namen eintippen musst. Völker und Stände mit Behandlungen lassen sich gar nicht löschen, nur archivieren, weil das Bestandsbuch vollständig bleiben muss.\n</div>\n</section>\n\n<!-- 5 -->\n<section id=\"voelker\">\n<h2><span class=\"nr\">5</span>Völker</h2>\n<h3>Volk anlegen</h3>\n<p>Auf der Seite des Stands <span class=\"knopf\">+ Neues Volk</span>. Pflicht ist nur der Name bzw. die Stocknummer. Dazu kommen Rasse, Jahrgang und Kennzeichnung der Königin, der <strong>Brutraum</strong> (Zarge aus deinem Beutensystem) mit der <strong>Anzahl</strong> (1 = einräumig, 2 = zweiräumig …), der <strong>Deckel</strong> (Standarddeckel oder ein Klimadeckel aus dem Lager) und optional ein Foto der Beute.</p>\n<figure class=\"schmal\" style=\"max-width:440px\"><img src=\"/anleitung/bilder/volk-neu.webp\" loading=\"lazy\" alt=\"Dialog Neues Volk anlegen\"><figcaption>Neues Volk anlegen, hier mit einer Königin aus dem Bestand.</figcaption></figure>\n<div class=\"tipp\"><strong>Königin gleich mit anlegen</strong>Gibst du hier Jahrgang oder Zeichen an, entsteht dazu automatisch eine Königin im Bereich <a href=\"#koeniginnen\">Königinnen</a>. Dort kannst du sie später um Abstammung und Begattung ergänzen.</div>\n<p><strong>Königin aus dem Bestand:</strong> Hast du freie Königinnen (Reserve, in keinem Volk), steht bei der Königin ein Umschalter <em>Neu erfassen | Vorhandene</em>. Bei <em>Vorhandene</em> wählst du sie aus der Liste. Ein kleiner Steckbrief zeigt Farbe, Zeichen, Rasse und Herkunft. Die Rasse übernimmt die App, solange du keine eigene einträgst. Im Lebenslauf der Königin steht danach „In ein Volk zugesetzt“. Königinnen, die schon in einem Volk sitzen, wählst du hier nicht. Dafür gibt es <em>Umweiseln</em> (siehe unten).</p>\n\n<h3>Die Seite eines Volkes (Stockkarte)</h3>\n<p>Ein Tipp auf die Kachel öffnet das Volk. Der Kopf ist auf allen Geräten gleich aufgebaut:</p>\n<ul>\n  <li>Links das Foto der Beute, daneben Name, <strong>Plaketten</strong> (Status, <em>QR gelernt</em>, <em>Fütterer drauf</em>) sowie Rasse, Betriebsweise (z.&nbsp;B. „2 × Zander ganz“) und ein Klimadeckel, falls vorhanden.</li>\n  <li>Darunter eine eigene Zeile für die <strong>Königin</strong>, die gerade im Volk sitzt. Ein Tipp darauf öffnet ihre Seite. Rechts daneben steht <span class=\"knopf\">Umweiseln</span>.</li>\n  <li>Die Knöpfe <span class=\"knopf\">Bearbeiten</span>, <span class=\"knopf\">Umziehen</span> (an einen anderen Stand, wird im Verlauf vermerkt; fehlt, solange du nur einen Stand hast), <span class=\"knopf\">QR-Code</span> (siehe <a href=\"#qr\">QR-Codes</a>) und <span class=\"knopf\">Status</span> (aktiv, aufgelöst, verkauft oder verloren).</li>\n</ul>\n<p>Darunter stehen das zuletzt erfasste <strong>Gewicht</strong> und drei Knöpfe: <span class=\"knopf\">Durchsicht erfassen</span>, <span class=\"knopf\">Maßnahme</span> und <span class=\"knopf\">Behandlung</span>. Alle drei öffnen ihr Formular direkt für dieses Volk.</p>\n<p>Hat das Volk <strong>offene Maßnahmen</strong>, stehen sie direkt darunter in einer eigenen Karte. Jede Maßnahme ist ein Kärtchen mit Farbleiste links und Termin: rot überfällig, gelb heute, grün in den nächsten 7 Tagen, grau später. Ab drei Maßnahmen ist die Karte zugeklappt und nennt nur, wie viele überfällig oder heute fällig sind. Ein Tipp klappt sie auf. Ein Haken erledigt sie gleich bei der Durchsicht, ohne Umweg über den alten Eintrag oder die Maßnahmen-Seite. Vertippt? <span class=\"knopf\">Rückgängig</span> in der Leiste unten holt sie zurück. Bei einer Maßnahme für mehrere Völker gilt der Haken nur für dieses Volk. Abgehakt wird nur hier, nicht im Verlauf.</p>\n<h3>Umweiseln</h3>\n<p>Setzt du eine neue Königin ein, tippst du in der Königin-Zeile auf <span class=\"knopf\">Umweiseln</span>. Im Fenster wählst du das Datum, die neue Königin (aus der Reserve, aus einem anderen Volk oder neu erfasst mit Jahrgang, Zeichen und Herkunft) und was mit der alten geschieht: <em>Abgedrückt</em>, <em>In Reserve / Ableger</em>, <em>Verkauft</em> oder <em>Verschwunden</em>. Beide Lebensläufe trägt die App selbst ein. Im Verlauf des Volks erscheint eine Karte „Umgeweiselt alt → neu“. <em>Bearbeiten</em> beim Volk ändert die Angaben der jetzigen Königin nur noch zum Korrigieren.</p>\n<figure class=\"schmal\" style=\"max-width:440px\"><img src=\"/anleitung/bilder/umweiseln.webp\" loading=\"lazy\" alt=\"Fenster Umweiseln\"><figcaption>Umweiseln: neue Königin aus dem Bestand, die alte wurde abgedrückt.</figcaption></figure>\n<p>Es folgt der <strong>Verlauf</strong> auf einer eigenen, leicht getönten Fläche, neueste zuerst und nach Saison gegliedert. Jede Karte hat links einen Farbstreifen: grün für Durchsicht und Königin, grau für Maßnahmen, honigfarben für Behandlungen. Die Kopfzeile jeder Saison fasst zusammen, z.&nbsp;B. „6 Durchsichten · 3 Maßnahmen · 1 Behandlung“, mit der letzten Bewertung, Varroa und Gewicht. Im Verlauf stehen diese Karten:</p>\n<ul>\n  <li><strong>Durchsichten:</strong> Jede Bewertung erscheint als kleiner Strahl mit grüner, gelber und roter Zone, einer Marke und dem Wertungstext, z.&nbsp;B. „Stark“ oder „Gut–Mittel“ (zwischen zwei Stufen). Gelb und rot tragen zusätzlich ein Warnzeichen. Alle übrigen Angaben stehen als kurze Chips darunter, nur was du wirklich ausgefüllt hast. Varroa über der Schadschwelle erscheint als roter Kasten. <span class=\"knopf\">Durchsicht öffnen ›</span> rechts oben öffnet den Eintrag.</li>\n  <li><strong>Maßnahmen</strong>, die ohne Durchsicht angelegt wurden: „○ offen“ mit Termin oder „✓ erledigt“. Stift und Mülleimer bearbeiten bzw. löschen sie. Abhaken geht oben unter <em>Offene Maßnahmen</em>.</li>\n  <li><strong>Behandlungen</strong> am Tag der Anwendung: Medikament, wogegen, Menge, Dauer und Wartezeit. Den vollständigen Nachweis gibt es unter <a href=\"#behandlungen\">Behandlungen</a>. Verfahren ohne Medikament (TBE, Bannwabe …) erscheinen ebenfalls hier.</li>\n  <li><strong>Königinnenwechsel:</strong> „Umgeweiselt alt → neu“ bzw. „Königin zugesetzt“. Die Saison-Zeile zählt sie mit.</li>\n</ul>\n<figure><img src=\"/anleitung/bilder/verlauf-durchsicht.webp\" loading=\"lazy\" alt=\"Durchsicht im Verlauf mit Mini-Strahlen und Chips\"><figcaption>Eine Durchsicht im Verlauf. Jede Wertung ist ein kleiner Strahl. Die übrigen Angaben stehen als Chips darunter.</figcaption></figure>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/verlauf-behandlung.webp\" loading=\"lazy\" alt=\"Behandlung im Verlauf\"><figcaption>Eine Behandlung im Verlauf.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/verlauf-massnahme.webp\" loading=\"lazy\" alt=\"Maßnahme im Verlauf\"><figcaption>Eine Maßnahme ohne Durchsicht.</figcaption></figure>\n</div>\n<p>Fotos im Verlauf öffnest du mit einem Tipp groß. Dort kannst du zoomen, zwischen den Fotos blättern und sie herunterladen; am iPhone legt <span class=\"knopf\">In Fotos sichern</span> das Bild direkt in die Fotos-App.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/volk.webp\" loading=\"lazy\" alt=\"Seite von Volk 1 mit Verlauf\"><figcaption>Volk 1: Kopf mit Königinzeile und <em>Umweiseln</em>, darunter die drei Knöpfe, die offenen Maßnahmen und der Verlauf.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-volk.webp\" loading=\"lazy\" alt=\"Volk 3 am Handy\"><figcaption>Volk 3 am Handy: überfällige Futterkontrolle, Durchsichten als Mini-Strahlen.</figcaption></figure>\n</div>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\" style=\"max-width:420px\"><img src=\"/anleitung/bilder/d-volk-status.webp\" loading=\"lazy\" alt=\"Fenster Status ändern\"><figcaption>Status ändern.</figcaption></figure>\n</div>\n</section>\n\n<!-- 6 -->\n<section id=\"stockkarte\">\n<h2><span class=\"nr\">6</span>Durchsicht erfassen</h2>\n<p>Im Volk auf <span class=\"knopf\">Durchsicht erfassen</span> tippen. Datum und Uhrzeit sind auf „jetzt“ gesetzt. Die Angaben sind in aufklappbare Abschnitte gegliedert, Brutraum und Bewertung sind schon offen. <strong>Du füllst nur aus, was du wirklich beobachtet hast</strong>, leere Abschnitte und unberührte Regler bleiben einfach leer. Unten steht immer sichtbar der Knopf <span class=\"knopf\">Durchsicht speichern</span>.</p>\n<table>\n  <tr><th>Abschnitt</th><th>Was hinein gehört</th></tr>\n  <tr><td>Brutraum</td><td>Haken nur für das, was du gesehen hast: Königin, Stifte, Larven, verdeckelte Brut, Weiselzellen, drohnenbrütig. Besetzte Wabengassen und bebrütete Waben stellst du mit + und − ein. Grau steht die Zahl vom letzten Mal; ein Tipp darauf übernimmt sie, das erste + zählt von dort weiter.</td></tr>\n  <tr><td>Waben</td><td>Genommene oder gegebene Leerwaben, Mittelwände, Brut- und Futterwaben, Baurahmen, ebenfalls mit „letztes Mal“.</td></tr>\n  <tr><td>Varroa</td><td>Zählweise (Puderzucker, Auswaschung, Gemülldiagnose), gezählte Milben, Probengröße bzw. Tage der Windel. Die App rechnet auf Milben je Tag bzw. Prozent um und vergleicht mit der Schadschwelle der Jahreszeit. Unter <em>Biotechnik</em> der Haken <em>Drohnenbrut geschnitten</em> und ein freies Feld. Verfahren mit Fahrplan wie TBE oder Bannwabe legst du unter <a href=\"#behandlungen\">Behandlungen</a> an. Tierarzneimittel gehören nicht hierher, sondern unter <a href=\"#behandlungen\">Behandlungen</a>.</td></tr>\n  <tr><td>Bewertung des Volkes</td><td>Regler für Volksstärke, Futtermenge, Sanftmut, Wabensitz, Schwarmtrieb, Legeleistung und Gesamteindruck, siehe unten. Dazu die Haken <em>Bienen haben mich angeflogen</em> und <em>Abgeschwärmt</em>.</td></tr>\n  <tr><td>Honigraum &amp; Ernte</td><td>Honigraum aufsetzen oder abnehmen, Ernte (die App schätzt die Menge aus den abgenommenen Zargen und Waben, du kannst sie anpassen) und Honigart.</td></tr>\n  <tr><td>Fütterung</td><td>Futterart und Menge in kg, dazu der Haken <em>Fütterer aufgesetzt</em>. Er ist so vorbelegt, wie es gerade am Volk ist; nimmst du den Haken weg, gilt der Fütterer als abgenommen.</td></tr>\n  <tr><td>Gewicht</td><td>Gewogenes Gewicht, einseitig oder vollständig. Wiegst du in Teilen, tippst du einfach „13+17“, die App rechnet „= 30 kg“. Der Knopf <span class=\"knopf\">+</span> neben dem Feld hilft am iPhone, dessen Zahlentastatur kein Plus hat.</td></tr>\n</table>\n<p>Unten folgen <strong>Notizen</strong>, <strong>Maßnahmen</strong> (eine pro Zeile, sie landen in der <a href=\"#massnahmen\">Maßnahmenliste</a>) und bis zu fünf <strong>Fotos</strong>, direkt mit der Handykamera oder aus der Mediathek.</p>\n<h3>Bewerten mit den Reglern</h3>\n<p>Jeder Regler hat sechs benannte Stufen, links die beste, rechts die schlechteste, z.&nbsp;B. bei der Volksstärke von „Sehr stark“ bis „Sehr schwach“, beim Schwarmtrieb von „Keiner“ über „Spielnäpfchen“ und „Bestiftet“ bis „Verdeckelt“. Zwischen zwei Stufen kannst du auch die Mitte wählen. Ein Regler ist erst gesetzt, wenn du ihn bewegst; dann färbt er sich grün, gelb oder rot. Das kleine × setzt ihn wieder auf „nicht bewertet“.</p>\n<p>Ein grauer, gestrichelter <strong>Ring</strong> zeigt, wo du das Volk beim letzten Mal eingestuft hast, solange der Regler leer ist zusätzlich als Text „Letztes Mal: Stark (04.10.)“. Übernommen wird davon nichts, du entscheidest jedes Mal neu.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\" style=\"flex-basis:380px;max-width:520px\"><img src=\"/anleitung/bilder/d-eintrag-dialog.webp\" loading=\"lazy\" alt=\"Durchsicht erfassen, Abschnitt Brutraum\"><figcaption>Brutraum: Haken für das Gesehene, Wabengassen mit „letztes Mal“.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:380px;max-width:520px\"><img src=\"/anleitung/bilder/d-eintrag-beurteilung.webp\" loading=\"lazy\" alt=\"Bewertung mit sechsstufigen Reglern\"><figcaption>Bewertung: sechs Stufen je Regler, der gestrichelte Ring zeigt die letzte Wertung.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:380px;max-width:520px\"><img src=\"/anleitung/bilder/d-eintrag-varroa.webp\" loading=\"lazy\" alt=\"Abschnitt Varroa\"><figcaption>Varroa: Zählweise und Milben, darunter Biotechnik.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-eintrag.webp\" loading=\"lazy\" alt=\"Bewertung am Handy\"><figcaption>Am Handy.</figcaption></figure>\n</div>\n<p>Drei Abschnitte, die oft gebraucht werden:</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/d-eintrag-honig.webp\" loading=\"lazy\" alt=\"Abschnitt Honigraum und Ernte\"><figcaption>Ernte: Zarge angeben. Die App schätzt die Menge, der Regler korrigiert.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/d-eintrag-fuetterung.webp\" loading=\"lazy\" alt=\"Abschnitt Fütterung\"><figcaption>Fütterung: Futterart und Menge. Der Haken sagt, ob der Fütterer drauf ist.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/d-eintrag-gewicht.webp\" loading=\"lazy\" alt=\"Abschnitt Gewicht mit 13+17\"><figcaption>Gewicht in Teilen: „13+17“ tippen, die App rechnet.</figcaption></figure>\n</div>\n<h3>Beim Speichern: kurze Rückfragen</h3>\n<p>Nach <span class=\"knopf\">Durchsicht speichern</span> kann die App bis zu drei kurze Fragen stellen. Nach der letzten Antwort speichert sie sofort, ein zweiter Tipp ist nicht nötig.</p>\n<ol>\n  <li><strong>Auffälligkeiten:</strong> Ist ein Wert kritisch (z.&nbsp;B. Varroa über der Schadschwelle, sehr wenig Futter, drohnenbrütig, abgeschwärmt), schlägt die App vor, gleich eine Maßnahme mit Termin anzulegen.</li>\n  <li><strong>Bewertung zur Königin:</strong> Sitzt eine Königin im Volk, fragt die App, ob die Bewertung auch in ihren Lebenslauf soll. Nur mit „Ja“ zählt die Durchsicht für ihre Bewertung, so entscheidest du selbst, was eingeht (z.&nbsp;B. nicht bei einer Durchsicht im Gewitter).</li>\n  <li><strong>Honig ins Lager:</strong> Bei einer neuen Ernte kannst du die Menge gleich in den Honigbestand im <a href=\"#lager\">Lager</a> buchen.</li>\n</ol>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/frage-massnahme.webp\" loading=\"lazy\" alt=\"Rückfrage Auffällige Bewertung mit Maßnahme\"><figcaption>Auffällig: Die App schlägt eine Maßnahme vor. Text und Termin kannst du ändern.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/frage-koenigin.webp\" loading=\"lazy\" alt=\"Rückfrage Bewertung zur Königin\"><figcaption>Königin: Nur mit „Ja“ zählt die Durchsicht für sie.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/frage-honig.webp\" loading=\"lazy\" alt=\"Rückfrage Honig ins Lager\"><figcaption>Honig: Die Menge ist vorbelegt. „Speichern“ bucht sie ins Lager.</figcaption></figure>\n</div>\n<div class=\"tipp\">\n  <strong>Nichts geht verloren</strong>\n  Während du tippst, sichert das Gerät deine Eingaben laufend als Entwurf. Schließt du das Fenster aus Versehen, ist beim nächsten Öffnen alles wieder da.\n</div>\n<h3 id=\"funkloch\">Speichern ohne Netz</h3>\n<p>Ist beim Speichern kein Netz da oder antwortet der Server nicht, legt die App die Durchsicht samt Fotos auf dem Handy ab. Du siehst kurz <em>Auf dem Handy gesichert</em>, tippst <span class=\"knopf\">OK</span> und machst am nächsten Volk weiter. Sobald wieder Verbindung da ist, sendet die App alles von selbst, auch wenn du sie erst zu Hause wieder öffnest. Du musst nichts tun.</p>\n<p>Das gilt genauso für <strong>neue Maßnahmen</strong> und fürs <strong>Abhaken</strong>: Ohne Netz schließt das Fenster wie gewohnt, eine abgehakte Maßnahme verschwindet aus der Liste. Beides wartet auf dem Handy und geht raus, sobald Netz da ist. Als „erledigt am“ zählt der Moment, in dem du getippt hast.</p>\n<ul>\n  <li><strong>Leiste oben:</strong> etwa „Offline. 2 Durchsichten, 1 Haken warten.“, dann „werden gesendet …“ und zum Schluss kurz „Alles gesendet.“ Antippen zeigt, was noch wartet.</li>\n  <li><strong>Im Verlauf des Volks</strong> steht eine wartende Durchsicht oder Maßnahme als gestrichelte Karte „Wartet auf Senden“. Ist sie angekommen, wird daraus die normale Karte.</li>\n  <li><strong>Langsames Netz:</strong> Dauert das Speichern länger, erscheint <span class=\"knopf\">Weitermachen, im Hintergrund senden</span>. Die Durchsicht ist dann schon gesichert.</li>\n  <li><strong>Abgemeldet:</strong> Ist deine Anmeldung abgelaufen, sagt die Leiste „Bitte anmelden“. Nach dem Anmelden geht alles raus.</li>\n  <li><strong>Nicht angenommen:</strong> Lehnt der Server eine Durchsicht ab, etwa weil das Volk inzwischen gelöscht ist, wird die Leiste rot. Du kannst sie <em>erneut senden</em>, <em>ins Formular holen</em> (Fotos dann neu wählen) oder <em>verwerfen</em>.</li>\n</ul>\n<p>Doppelt kommt nichts an: Hat der Server schon gespeichert und nur die Antwort ging im Funkloch verloren, erkennt er die Durchsicht wieder.</p>\n<h3>Einträge ansehen und korrigieren</h3>\n<p><span class=\"knopf\">Durchsicht öffnen ›</span> an einer Durchsicht im Verlauf öffnet den Eintrag „Durchsicht vom …“. Er öffnet sich zunächst <strong>zum Lesen</strong>, damit du am Stand nichts aus Versehen verstellst. Zum Ändern legst du oben den Schalter auf <em>Bearbeiten</em> um. Dort kannst du auch Fotos ergänzen oder entfernen, Maßnahmen abhaken oder den Eintrag löschen. <span class=\"knopf\">✕ Durchsicht schließen</span> oben links (und unten nochmal) bringt dich zurück zu genau dieser Karte im Verlauf.</p>\n<figure class=\"handy\"><img src=\"/anleitung/bilder/eintrag-lesen.webp\" loading=\"lazy\" alt=\"Eintrag ansehen mit Schalter Nur lesen\"><figcaption>Der Eintrag ist erst gesperrt. Der Schalter oben gibt ihn frei.</figcaption></figure>\n<h3 id=\"sammel\">Mehrere Völker auf einmal</h3>\n<p>Wenn du am Stand mehrere Völker gleich behandelt hast, zum Beispiel alle gefüttert oder bei allen eine Windel eingelegt, nimmst du die Knöpfe <span class=\"knopf\">Durchsicht erfassen</span> und <span class=\"knopf\">Maßnahme</span> auf der <strong>Seite des Stands</strong>.</p>\n<ol class=\"schritte\">\n  <li>Völker antippen (der farbige Punkt ist die Zeichenfarbe der Königin) oder <span class=\"knopf\">Alle wählen</span>. Oben siehst du, wie viele gewählt sind.</li>\n  <li><span class=\"knopf\">Weiter</span>. Über <em>ändern</em> neben „Für: …“ kommst du zurück zur Auswahl, deine Eingaben bleiben dabei erhalten.</li>\n  <li>Durchsicht bzw. Maßnahme ausfüllen und speichern. Der Knopf sagt, wie viele Einträge entstehen.</li>\n</ol>\n<p>Jedes gewählte Volk bekommt einen eigenen, vollständigen Eintrag in seinem Verlauf bzw. eine eigene Maßnahme. Die Fragen „Bewertung zur Königin?“ und „Honig ins Lager?“ stellt die App nur bei einem einzelnen Volk, weil beides am einzelnen Volk hängt.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\" style=\"flex-basis:380px;max-width:520px\"><img src=\"/anleitung/bilder/d-sammel-auswahl.webp\" loading=\"lazy\" alt=\"Auswahl der Völker am Stand\"><figcaption>Auswahl am Stand.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:380px;max-width:520px\"><img src=\"/anleitung/bilder/d-sammel-formular.webp\" loading=\"lazy\" alt=\"Durchsicht für Volk 2 und Volk 3\"><figcaption>Eine Durchsicht „Für: Volk 2, Volk 3“, der Knopf sagt „2 Durchsichten speichern“.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:380px;max-width:520px\"><img src=\"/anleitung/bilder/d-sammel-massnahme.webp\" loading=\"lazy\" alt=\"Maßnahme für alle Völker des Stands\"><figcaption>Eine Maßnahme für alle drei Völker.</figcaption></figure>\n</div>\n</section>\n\n<!-- 7 -->\n<section id=\"massnahmen\">\n<h2><span class=\"nr\">7</span>Maßnahmen und Kalender</h2>\n<p>Unter <strong>Maßnahmen</strong> steht alles, was zu tun ist, über alle Völker hinweg, offene oben, erledigte unten. Ein Haken links erledigt eine Maßnahme. Hast du dich vertippt, holt <span class=\"knopf\">Rückgängig</span> in der Leiste, die ein paar Sekunden unten erscheint, sie zurück.</p>\n<ul>\n  <li><strong>Farben:</strong> Offene Maßnahmen sind Kärtchen mit Farbleiste links und Termin-Plakette, z.&nbsp;B. „Überfällig · 16.10.“, „Heute“ oder „Fr 23.10.“. Rot ist überfällig, gelb heute fällig, grün in den nächsten 7 Tagen. Später fällige bleiben grau.</li>\n  <li><strong>Sammelmaßnahmen</strong> (eine Maßnahme für mehrere Völker) stehen als eine Zeile, z.&nbsp;B. „3 Völker · Obstwiese · Fällig: 21.10.2026“. Die Zeile zeigt, wie viele schon erledigt sind („1/3 erledigt“). Ein Tipp klappt sie auf: Je Volk eine schmale Zeile mit Haken, Stift und Mülleimer, am Rechner in mehreren Spalten. Mit <span class=\"knopf\">Alle 3 erledigt</span> hakst du alle auf einmal ab.</li>\n  <li><strong>Verfahren</strong> ohne Medikament (TBE, Bannwabe …) stehen hier nur, wenn du beim Verfahren <em>In Maßnahmen übernehmen</em> angehakt hast. Dann als eine Zeile mit dem nächsten Schritt und Termin. Aufgeklappt siehst du alle Schritte, <span class=\"knopf\">Nächsten Schritt erledigt</span> hakt ihn ab.</li>\n  <li><strong>Kalender:</strong> Unter der Liste zeigt ein Monatskalender, an welchen Tagen Maßnahmen anstehen (rot überfällig, gelb heute, grün geplant). Der heutige Tag ist ein gefüllter Kreis. Am Rechner und Tablet siehst du zwei Monate nebeneinander, am Handy einen. Tippst du einen Tag an, zeigt die Liste nur dessen Maßnahmen.</li>\n</ul>\n<p>Mit <span class=\"knopf\">+ Neue Maßnahme</span> öffnet sich ein Fenster: für <strong>einzelne Völker</strong> (antippen, mehrere möglich), einen <strong>ganzen Stand</strong> oder <strong>alle Stände</strong>. Unter <em>Standardarbeit</em> stehen häufige Arbeiten zur Auswahl (z.&nbsp;B. Mäusegitter, Einfüttern), oder du tippst frei ein und setzt einen Termin.</p>\n<figure class=\"schmal\" style=\"max-width:440px\"><img src=\"/anleitung/bilder/massnahme-neu.webp\" loading=\"lazy\" alt=\"Fenster Neue Maßnahme\"><figcaption>Eine Maßnahme für Volk 2 und Volk 3, fällig am 30.10.</figcaption></figure>\n<figure><img src=\"/anleitung/bilder/massnahmen.webp\" loading=\"lazy\" alt=\"Maßnahmenübersicht mit Kalender\"><figcaption>Maßnahmen: oben die offenen, die Futterkontrolle ist überfällig. Darunter der Kalender und die erledigten.</figcaption></figure>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/massnahmen-gruppe.webp\" loading=\"lazy\" alt=\"Aufgeklappte Sammelmaßnahme\"><figcaption>Die Sammelmaßnahme „Varroa-Windel einlegen“ aufgeklappt.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-massnahmen.webp\" loading=\"lazy\" alt=\"Maßnahmen am Handy\"><figcaption>Am Handy.</figcaption></figure>\n</div>\n<h3>Maßnahmen im eigenen Kalender</h3>\n<p>Unter <em>Einstellungen → Kalender-Abo</em> bekommst du eine persönliche Kalenderadresse. Abonnierst du sie im Kalender von iPhone, iPad oder Rechner, erscheinen alle offenen Maßnahmen mit Termin dort, samt Erinnerung, ohne dass du die App öffnen musst. Die genaue Anleitung fürs iPhone steht auf der Seite zum Aufklappen. Erinnerungszeit, Farbe und Titel der Termine stellst du darunter ein.</p>\n<figure class=\"schmal\"><img src=\"/anleitung/bilder/kalender.webp\" loading=\"lazy\" alt=\"Einstellungen für das Kalender-Abo\"><figcaption>Kalender-Abo einrichten. Die Adresse ist persönlich, gib sie nicht weiter. Mit <em>Neue Adresse erzeugen</em> machst du eine bekannt gewordene Adresse ungültig.</figcaption></figure>\n</section>\n\n<!-- 8 -->\n<section id=\"koeniginnen\">\n<h2><span class=\"nr\">8</span>Königinnen</h2>\n<p>Der Bereich hat zwei Reiter: <strong>Bestand</strong> (alle Königinnen) und <strong>Zucht</strong> (Zuchtserien, siehe <a href=\"#zucht\">Zucht</a>).</p>\n<h3>Bestand</h3>\n<p>Die Liste ist nach Ständen gruppiert; Königinnen ohne Volk (Reserve, Ableger, im Käfig) und nicht mehr vorhandene stehen am Ende. Das farbige Quadrat zeigt Zeichenfarbe und Jahrgang. Mit Suche und Filtern (Stand, Jahrgang, Begattung) findest du schnell die richtige, mit <em>Liste / Kacheln</em> wechselst du die Ansicht. Den gelben <strong>Stern</strong> setzt du selbst auf der Seite einer Königin, um herausragende Tiere zu markieren.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/koeniginnen.webp\" loading=\"lazy\" alt=\"Königinnenbestand\"><figcaption>Die drei Königinnen des Beispielstands.</figcaption></figure>\n  <figure class=\"handy\"><img src=\"/anleitung/bilder/handy-koeniginnen.webp\" loading=\"lazy\" alt=\"Königinnen am Handy\"><figcaption>Am Handy: Filter als Chips, <em>+ Königin</em> als schwebender Knopf.</figcaption></figure>\n</div>\n<h3>Neue Königin</h3>\n<p><span class=\"knopf\">+ Neue Königin</span>. Eine Kennung wird vorgeschlagen. Dazu kommen Jahrgang und Zeichen (die Farbe richtet sich nach dem Jahrgang), Herkunft (eigene Nachzucht, Nachschaffung, Schwarm, Zukauf), Mutter, Begattung (Belegstelle, Standbegattung, künstliche Besamung) und das Volk, in das sie kommt. Belegstellen legst du einmal unter <em>Einstellungen → Belegstellen</em> an, dort auch die Drohnenvölker je Jahr.</p>\n<figure><img src=\"/anleitung/bilder/koenigin-neu.webp\" loading=\"lazy\" alt=\"Formular Neue Königin\"><figcaption>Neue Königin anlegen.</figcaption></figure>\n<h3>Seite einer Königin</h3>\n<ul>\n  <li><strong>Stammdaten</strong> und darunter die <strong>Bewertung</strong>: der Schnitt aller übernommenen Durchsichten je Kriterium als Note (1 ist die beste), eine Gesamtnote, dazu Honigertrag und Brutwaben. Nur hier bei den Königinnen stehen Noten, damit sich Königinnen vergleichen lassen; auf Stockkarte und Stand siehst du die Wertungstexte.</li>\n  <li><strong>Abstammung</strong> mit <em>Mutterseite</em> und <em>Vaterseite</em>, dazu die Töchter. Die Vaterseite zeigt bei Belegstellen-Begattung die Belegstelle, das Belegjahr und die Drohnenvölker, die dort in diesem Jahr standen. Bei künstlicher Besamung die Vaterlinie, bei Standbegattung „Drohnen unbekannt“. Das Belegjahr ist das Jahr von „Begattung von“, sonst der Jahrgang. <em>Ganzer Stammbaum</em> zeigt alle Linien, jede Königin mit „♂ Belegstelle Jahr“.</li>\n  <li><strong>Lebenslauf</strong>: Schlupf, Belegstelle, Zusetzen, Entnehmen, Verkauf, Tod und Bewertungen. Einzelne Kriterien einer Bewertung kannst du abhaken, wenn sie verfälscht waren.</li>\n  <li><strong>Zuchtkarte</strong>: einmal erstellen (die Vaterseite ist mit den Drohnenvölkern vorbelegt), bei Bedarf anpassen und drucken (mehrere Karten auf einem Bogen über <em>Dokumente → Zuchtkarten drucken</em>).</li>\n</ul>\n<figure class=\"schmal\" style=\"max-width:440px\"><img src=\"/anleitung/bilder/koenigin-lebenslauf.webp\" loading=\"lazy\" alt=\"Lebenslauf mit Ereignis In ein Volk zugesetzt\"><figcaption>Lebenslauf: Ereignis, Datum und Volk wählen. Sitzt dort schon eine Königin, kommt sie in die Reserve.</figcaption></figure>\n<figure><img src=\"/anleitung/bilder/koenigin.webp\" loading=\"lazy\" alt=\"Seite einer Königin mit Stammdaten und Bewertung\"><figcaption>Die Königin aus Volk 1 mit Stern, Bewertung und Abstammung mit Vaterseite.</figcaption></figure>\n<figure><img src=\"/anleitung/bilder/stammbaum.webp\" loading=\"lazy\" alt=\"Stammbaum\"><figcaption>Der Stammbaum über alle Generationen. ♂ zeigt Belegstelle und Belegjahr.</figcaption></figure>\n</section>\n\n<!-- 9 -->\n<section id=\"zucht\">\n<h2><span class=\"nr\">9</span>Zucht</h2>\n<p>Unter <em>Königinnen → Zucht</em> planst du Zuchtserien. Bei <span class=\"knopf\">+ Neue Serie</span> wählst du Zuchtmutter, Zuchtvolk, Pflegeverfahren (z.&nbsp;B. weiselloses Pflegevolk, Starter/Finisher, Brutschrank), Pflegevolk, Umlarvtag und die geplante Begattung.</p>\n<figure><img src=\"/anleitung/bilder/zucht-neu.webp\" loading=\"lazy\" alt=\"Neue Zuchtserie\"><figcaption>Neue Zuchtserie: die Zuchtmutter mit ihren Noten auswählen.</figcaption></figure>\n<p>Aus dem Umlarvtag errechnet die App den ganzen <strong>Zeitplan</strong>: Pflegevolk vorbereiten, Annahme kontrollieren, verschulen, Schlupf, Begattung, Eilage. Jeder Schritt erscheint als Maßnahme beim jeweiligen Volk und auf Wunsch im Kalender-Abo. Rechts trägst du die <strong>Zahlen</strong> nach (umgelarvt, angenommen, verdeckelt, geschlüpft). Nach dem Schlupf legst du unten die <strong>nachgezogenen Königinnen</strong> in einem Rutsch an, Mutter und Jahrgang sind dann schon eingetragen.</p>\n<figure><img src=\"/anleitung/bilder/serie.webp\" loading=\"lazy\" alt=\"Zuchtserie mit Zeitplan\"><figcaption>Eine Zuchtserie mit Überblick, Zahlen und Zeitplan.</figcaption></figure>\n</section>\n\n<!-- 10 -->\n<section id=\"behandlungen\">\n<h2><span class=\"nr\">10</span>Behandlungen (Bestandsbuch)</h2>\n<p>Hier dokumentierst du die Anwendung von Tierarzneimitteln, so wie es das Bestandsbuch verlangt.</p>\n<ol class=\"schritte\">\n  <li><strong>Medikament anlegen</strong> (<span class=\"knopf\">Medikamente</span> → <em>Medikament anlegen</em>): Name, Wirkstoff, Zulassungsnummer, Wartezeit, Charge, Verfallsdatum. <strong>Lieferant und Belegnummer</strong> sind Pflicht. Für die gängigen Varroa-Mittel gibt es <strong>Vorlagen</strong>: Unter <em>Gängige Mittel als Vorlage</em> tippst du beim Mittel auf <span class=\"knopf\">Aktivieren</span>. Name, Wirkstoff, Einheit und Wartezeit sind dann schon ausgefüllt. Du trägst nur noch deine Packung ein: Lieferant, Belegnummer, Kaufdatum und Charge. Diese vier sind bei einer Vorlage Pflicht. Gleiche die Angaben kurz mit der Packung ab. Lade die Rechnung oder Verschreibung als <strong>Erwerbsbeleg</strong> hoch, sie gehört zum Nachweis. Fehlt etwas, zeigt die App das beim Medikament und oben in der Übersicht an.</li>\n  <li><strong>Behandlung erfassen</strong> (<span class=\"knopf\">+ Neue Behandlung</span>, oder auf der Volk-Seite <span class=\"knopf\">Behandlung</span>). Oben steht der Umschalter <em>Mit Medikament | Ohne Medikament</em>. Mit Medikament: Medikament, behandelt gegen (z.&nbsp;B. Varroose), Völker (einzeln oder ganzer Stand), Datum, bei Langzeitverdunstern das Ende, Menge je Volk (Komma erlaubt) und Anwender. Die App nennt dir den Tag, ab dem frühestens wieder Honig entnommen werden darf.</li>\n  <li><strong>Nachweis als PDF</strong>: Jahr und Umfang wählen, <span class=\"knopf\">PDF erstellen</span>. Die Datei bleibt gespeichert und lässt sich jederzeit wieder herunterladen oder verschicken.</li>\n</ol>\n<p>Die dokumentierten Behandlungen sind nach Jahren in Reitern sortiert. Jede Behandlung erscheint außerdem im Verlauf der behandelten Völker.</p>\n<h3>Verfahren ohne Medikament</h3>\n<p>Bei <em>Ohne Medikament</em> wählst du ein Verfahren: <strong>Totale Brutentnahme (TBE)</strong>, <strong>Teil-Brutentnahme</strong>, <strong>Bannwabenverfahren</strong>, <strong>Königin käfigen</strong> oder <strong>Sonstiges</strong>. Dazu Völker und Beginn. Menge und Wartezeit entfallen, ins Bestandsbuch kommt es nicht.</p>\n<ul>\n  <li><strong>Fahrplan:</strong> Aus dem Beginn rechnet die App alle Schritte mit Tag und Termin, etwa Brut entnehmen, Befall kontrollieren oder die Oxalsäure-Behandlung danach.</li>\n  <li><strong>Bannwabe:</strong> Unter <em>Ablauf</em> wählst du 3 × 9 Tage (LWG Bayern, Vorgabe), 3 × 7 Tage (apisuisse), 4 × 7 Tage oder 2 × 12 Tage als Doppeltasche (12/24).</li>\n  <li><strong>In Maßnahmen übernehmen:</strong> Angehakt stehen die Schritte auch unter <a href=\"#massnahmen\">Maßnahmen</a>, im Kalender und im Kalender-Abo. Sonst nur beim Verfahren und im Verlauf am Volk.</li>\n  <li><strong>Seite des Verfahrens:</strong> Fahrplan mit Haken je Schritt, für alle Völker auf einmal. Beim Medikamenten-Schritt öffnet <span class=\"knopf\">Behandlung eintragen</span> das Formular schon ausgefüllt und hakt den Schritt danach ab. <em>Bearbeiten</em> verschiebt die offenen Termine mit.</li>\n</ul>\n<p>Verfahren stehen in der Liste unter Behandlungen und im Verlauf der Völker. Käfigen und Bannwabe trägt die App auch in den Lebenslauf der Königin ein.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/behandlung-bio.webp\" loading=\"lazy\" alt=\"Neue Behandlung ohne Medikament\"><figcaption>Bannwabenverfahren für Volk 2 und Volk 3 mit Fahrplan. Erledigte Schritte hakst du gleich mit ab.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/verfahren.webp\" loading=\"lazy\" alt=\"Seite eines Verfahrens\"><figcaption>Die Seite des Verfahrens mit allen Schritten.</figcaption></figure>\n</div>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/medikamente.webp\" loading=\"lazy\" alt=\"Medikamentenliste\"><figcaption>Medikamente: bei den Beispielmedikamenten fehlt der Beleg.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/medikament-neu.webp\" loading=\"lazy\" alt=\"Formular Medikament anlegen\"><figcaption>Medikament anlegen. Lieferant und Belegnummer sind Pflicht.</figcaption></figure>\n</div>\n<figure><img src=\"/anleitung/bilder/behandlung-neu.webp\" loading=\"lazy\" alt=\"Neue Behandlung\"><figcaption>Neue Behandlung. Oben der Umschalter Mit/Ohne Medikament.</figcaption></figure>\n<figure><img src=\"/anleitung/bilder/behandlungen.webp\" loading=\"lazy\" alt=\"Übersicht Behandlungen mit PDF-Export\"><figcaption>Übersicht: Hinweise auf fehlende Angaben, PDF-Nachweis und die Ameisensäure-Behandlung des Beispielstands.</figcaption></figure>\n<figure><img src=\"/anleitung/bilder/nachweis.webp\" loading=\"lazy\" alt=\"Vorschau des Behandlungsnachweises\"><figcaption>Der Nachweis in der Vorschau: oben die Übersicht je Volk, darunter jede Anwendung einzeln.</figcaption></figure>\n<div class=\"tipp\"><strong>Stornieren statt löschen</strong>Eine falsch erfasste Behandlung wird storniert (mit Grund), nicht gelöscht. So bleibt der Nachweis lückenlos. Stornierte Behandlungen erscheinen nicht mehr im Verlauf des Volkes, wohl aber im Bestandsbuch.</div>\n</section>\n\n<!-- 11 -->\n<section id=\"dokumente\">\n<h2><span class=\"nr\">11</span>Dokumente</h2>\n<p>Bilder und PDFs mit Kategorie (Gesundheitszeugnis, Rechnung, Vertrag, Versicherung, Genehmigung, Anleitung, Sonstiges oder eigene). Beim Hochladen kannst du ein Dokument mit einem Stand, einer Königin und/oder mehreren Völkern verknüpfen. Es erscheint dann zusätzlich dort. Die Liste lässt sich durchsuchen und nach Kategorie filtern. Hier liegen auch die erzeugten Behandlungsnachweise, die Lagerlisten, die Medikamenten-Belege und der Druck der Zuchtkarten.</p>\n<p><strong>Per E-Mail senden:</strong> Hast du unter <em>Einstellungen → E-Mail-Versand</em> dein Postfach eingerichtet, bekommt jede Zeile ein Kästchen. Wähle die Dokumente aus und tippe auf <span class=\"knopf\">Per E-Mail senden</span>: Empfänger, Betreff und Text eintragen, auf Wunsch eine Kopie an dich. Die Dateien hängt die App selbst an.</p>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/dokument-neu.webp\" loading=\"lazy\" alt=\"Dokument hochladen\"><figcaption>Dokument hochladen und mit dem Stand verknüpfen.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/dokumente.webp\" loading=\"lazy\" alt=\"Dokumentenliste\"><figcaption>Die Dokumentenliste.</figcaption></figure>\n</div>\n</section>\n\n<!-- 12 -->\n<section id=\"lager\">\n<h2><span class=\"nr\">12</span>Lager</h2>\n<p>Tippst du im Menü auf <em>Lager</em>, klappt darunter eine Auswahl auf: <em>Material</em> oder <em>Erzeugnisse</em>. Am Rechner klappt „Lager“ in der Seitenleiste auf und bleibt offen, solange du im Lager bist. Oben auf beiden Seiten wechselst du mit dem Umschalter direkt zur anderen.</p>\n<p><strong>Material:</strong> Bei den Zargen trägst du den Gesamtbestand ein. Wie viele davon im Einsatz sind, rechnet die App selbst aus Bruträumen und aufgesetzten Honigräumen aus. Genauso bei den <strong>Klimadeckeln</strong>: Gesamtbestand eintragen, „im Einsatz“ zählt die Völker, denen du den Deckel zugeordnet hast. Sonstiges Material (Mittelwände, Futter, Gläser …) legst du frei mit Menge, Einheit und Lagerort an.</p>\n<h3>Erzeugnisse</h3>\n<p>Je Erzeugnis gibt es einen Chip: Honig, Wachs, Propolis, Pollen und eigene. Darunter steht der Bestand als Liste. Ein Posten ist ein Gebinde mit Sorte, Zustand und Lagerort, z.&nbsp;B. „Eimer 25 kg · Frühtracht · 2 Stück“. Was nicht in einem Gebinde liegt, steht als lose Menge darunter: bei kg und g als „Gewicht“, bei Stück oder Liter als „Menge“. Stückzahlen zeigt die App ohne Komma.</p>\n<p><strong>Sortieren:</strong> Ab zwei Posten wählst du neben dem Einlagern-Knopf <em>Sortieren nach Sorte | Gebinde</em>. Je Gruppe steht eine Zwischenzeile mit der Summe. Nach Gebinde kommen Eimer, Gläser, Sonstige und zuletzt die lose Menge. Jedes Gerät merkt sich deine Wahl.</p>\n<ol class=\"schritte\">\n  <li><strong>Einlagern:</strong> <span class=\"knopf\">+ Honig einlagern</span> tippen. Oben <em>Eimer</em>, <em>Gläser</em> oder <em>Gewicht</em> antippen, darunter die Größe. Fehlt eine Größe, legst du sie mit „+ Größe“ an, z.&nbsp;B. „400 g“. Dann Anzahl, Sorte, Lagerort und Grund (Ernte, Zukauf, Bestandskorrektur, Sonstiges) wählen. Der Lagerort ist mit dem vom letzten Mal vorbelegt. Zustand, Datum und Notiz stehen unter „Weitere Angaben“.</li>\n  <li><strong>Auslagern:</strong> Beim Posten auf <span class=\"knopf\">Auslagern</span> tippen. Anzahl und Grund wählen, fertig. Mehr als vorhanden geht nicht.</li>\n  <li><strong>Abfüllen:</strong> Beim Posten, aus dem du abfüllst, auf <span class=\"knopf\">Auslagern</span> tippen und den Grund <em>Abfüllen</em> wählen. Mit + zählst du die gefüllten Gläser. Die App bucht sie ein. Ein angebrochener Rest bleibt unter „Gewicht“ stehen.</li>\n</ol>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/lager-einlagern.webp\" loading=\"lazy\" alt=\"Fenster Honig einlagern\"><figcaption>Einlagern: 2 Eimer Frühtracht aus der Ernte, in den Keller.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/lager-auslagern.webp\" loading=\"lazy\" alt=\"Fenster Auslagern\"><figcaption>Auslagern: 4 Gläser verkauft. Unten steht, was übrig bleibt.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:240px;max-width:360px\"><img src=\"/anleitung/bilder/lager-abfuellen.webp\" loading=\"lazy\" alt=\"Fenster Abfüllen in Gläser\"><figcaption>Abfüllen: 12 Gläser aus einem Eimer. Die App rechnet den Rest aus.</figcaption></figure>\n</div>\n<p>Honig aus einer Ernte musst du nicht von Hand buchen. Die Durchsicht fragt beim Speichern danach. Ein eigenes Erzeugnis legst du mit <span class=\"knopf\">+ Neu</span> am Ende der Chips an (Name und Einheit kg, g, Stück oder Liter). Eigene Erzeugnisse lassen sich darunter umbenennen und löschen, löschen aber nur ohne Bestand. Honig, Wachs, Propolis und Pollen bleiben fest. Sorten, Gebinde, Preise und den Schalter „Eimer einzeln wiegen“ findest du unter <em>Einstellungen → Lager</em>.</p>\n<p><strong>Eimer einzeln wiegen:</strong> Ist der Schalter an, fragt das Einlagern je Eimer nach dem echten Gewicht (leer = Nennwert). Jeder Eimer bekommt eine Nummer. Die Liste zeigt Anzahl und echtes Gewicht, <span class=\"knopf\">Gewichte</span> klappt die einzelnen Eimer auf. Ältere Eimer ohne Gewicht wiegst du dort mit <span class=\"knopf\">Nachwiegen</span> nach. Beim Auslagern und Abfüllen hakst du an, welche Eimer es sind. Abfüllen schlägt Gläser der größten Größe vor. Der Rest bleibt im Eimer, kommt unter „Gewicht“ oder wird als Schwund ausgebucht. Gläser zählen immer nach Nennwert.</p>\n<p><strong>Warenwert:</strong> Schaltest du unter <em>Einstellungen → Lager</em> den Warenwert an, zeigt jeder Posten seinen Wert, z.&nbsp;B. „50 × 4,50 € = 225,00 €“. Die Zwischenzeilen tragen die Summe, darunter steht der Wert des Erzeugnisses und aller Erzeugnisse. Posten ohne Preis zählen nicht mit, ein Hinweis sagt das. Beim Einlagern steht dann ein Feld <em>Preis je Stück</em> bzw. <em>Preis je kg</em>, vorbelegt aus der Preisliste. Änderst du ihn, ändert sich die Preisliste für diese Sorte und Größe.</p>\n<p><strong>Lagerlisten:</strong> <span class=\"knopf\">PDF erstellen</span> neben Material bzw. Bestand erzeugt eine Bestandsliste mit Lagerorten und dem, was gerade an den Völkern im Einsatz ist. Mit Warenwert kommen Preis und Wert dazu, bei Honig eine Tabelle „Warenwert nach Sorte“. Bei Einzelgewichten stehen die Eimer einzeln darunter. <strong>Buchungen als PDF</strong> unten bei den Erzeugnis-Lagerlisten: Zeitraum (Vorgabe 1.1. bis heute) und Erzeugnis wählen. Das PDF zeigt Anfang, Zugänge, Abgänge und Ende, dazu jede Buchung, älteste zuerst. Alle PDFs liegen unten auf der jeweiligen Lager-Seite und unter Dokumente.</p>\n<figure><img src=\"/anleitung/bilder/lager.webp\" loading=\"lazy\" alt=\"Lager, Erzeugnisse\"><figcaption>Erzeugnisse mit eingeschaltetem Warenwert, nach Sorte sortiert: je Posten Anzahl × Preis, unten die Summe.</figcaption></figure>\n<figure><img src=\"/anleitung/bilder/lager-material.webp\" loading=\"lazy\" alt=\"Lager, Material\"><figcaption>Material: Zargen mit „im Einsatz“ und „verfügbar“, Klimadeckel, sonstiges Material.</figcaption></figure>\n</section>\n\n<!-- 13 -->\n<section id=\"qr\">\n<h2><span class=\"nr\">13</span>QR-Codes und Scannen</h2>\n<p>Mit einem QR-Aufkleber an jeder Beute öffnest du am Stand per Scan sofort die richtige Stockkarte.</p>\n<ol class=\"schritte\">\n  <li><strong>Codes erzeugen:</strong> <em>Einstellungen → QR-Codes</em>, Anzahl wählen, PDF-Bogen öffnen und über den Drucken-Befehl des Browsers drucken. Fertige QR-Karten aus dem Handel funktionieren ebenso.</li>\n  <li><strong>Anlernen:</strong> Auf der Volk-Seite den Knopf <span class=\"knopf\">QR-Code</span> tippen und den Aufkleber scannen. Gehört der Code schon zu einem anderen Volk, fragt die App nach. Danach trägt das Volk die Plakette <em>QR gelernt</em>.</li>\n  <li><strong>Ändern oder entfernen:</strong> Ist schon ein Code angelernt, öffnet derselbe Knopf <em>QR-Code bearbeiten</em>. <span class=\"knopf\">Neuen anlernen</span> ersetzt den alten Code, <span class=\"knopf\">Code löschen</span> trennt ihn nach einer Rückfrage vom Volk.</li>\n  <li><strong>Scannen:</strong> Menüpunkt <em>Scannen</em> öffnet die Kamera und springt zur Stockkarte. Selbst erzeugte Codes funktionieren auch mit der normalen Kamera-App des Handys.</li>\n</ol>\n<div class=\"hinweis\">\n  <strong>Kamera fragt jedes Mal?</strong>\n  Safari am iPhone und iPad fragt ab Werk bei jedem Scan neu nach der Kamera. Dauerhaft erlaubst du sie in der <em>Einstellungen</em>-App des iPhones unter <em>Apps → Safari → Kamera → Erlauben</em>. Das gilt auch, wenn du die Imkereiverwaltung vom Home-Bildschirm startest. Solange die Kamera nicht dauerhaft erlaubt ist, zeigt die App unter dem Kamerabild einen Hinweis für dein Gerät.\n</div>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/qr-codes.webp\" loading=\"lazy\" alt=\"QR-Codes erzeugen\"><figcaption>QR-Codes als Druckbogen erzeugen.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/scannen.webp\" loading=\"lazy\" alt=\"Scannen-Seite\"><figcaption>Scannen (in der Anleitung ohne Kamerabild).</figcaption></figure>\n</div>\n<figure class=\"schmal\" style=\"max-width:420px\"><img src=\"/anleitung/bilder/d-volk-qr.webp\" loading=\"lazy\" alt=\"Fenster QR-Code bearbeiten\"><figcaption>QR-Code bearbeiten bei einem Volk mit angelerntem Code.</figcaption></figure>\n</section>\n\n<!-- 14 -->\n<section id=\"velutina\">\n<h2><span class=\"nr\">14</span>Velutina: Asiatische Hornisse</h2>\n<p>Der Bereich hat zwei Reiter: <strong>Meldungen</strong> und <strong>Nestsuche</strong>.</p>\n<h3>Meldungen (nur Baden-Württemberg)</h3>\n<p>Die App holt alle paar Stunden die geprüften Fundmeldungen der Asiatischen Hornisse aus der Fundortkarte der LUBW (Landesanstalt für Umwelt Baden-Württemberg). Solche Daten gibt es nur für Baden-Württemberg. Trag deshalb unter <em>Einstellungen → Bienenhalter</em> dein Bundesland ein: Liegt dein Betrieb in einem anderen Land, blendet die App Karte und Warnungen aus, die Nestsuche bleibt.</p>\n<ul>\n  <li><strong>Karte:</strong> Nester und Einzeltiere der Saison, deine Stände, um jeden Stand ein roter <strong>Akutbereich</strong> (Vorgabe 2 km) und ein gelber <strong>Warnbereich</strong> (Vorgabe 5 km). Beide stellst du mit den Schiebern über der Karte ein.</li>\n  <li><strong>Warnungen:</strong> Taucht eine <em>neue</em> Meldung in einem Bereich auf, erscheint eine Zahl am Menüpunkt und ein roter bzw. gelber Kasten auf der Startseite. Auf jeder Stand-Seite zeigt der Kasten <em>Asiatische Hornisse</em>, wie es um diesen Stand steht. Mit eingerichteter E-Mail bekommst du neue Meldungen auch per Mail.</li>\n</ul>\n<figure><img src=\"/anleitung/bilder/velutina.webp\" loading=\"lazy\" alt=\"Velutina-Karte mit Akut- und Warnbereich\"><figcaption>Meldungen: Akut- und Warnbereich um den Beispielstand (in der Anleitung ohne Kartenhintergrund und ohne Meldungen).</figcaption></figure>\n<h3>Nestsuche per Locktopf</h3>\n<p>Für die Suche nach einem Nest legst du eine <span class=\"knopf\">Neue Nestsuche</span> an und setzt <strong>Locktöpfe</strong> auf die Karte, per Antippen oder per GPS an deinem Standort. Je Locktopf markierst du Hornissen mit einer Farbe und hältst fest:</p>\n<ul>\n  <li>die <strong>Abflugrichtung</strong>, per Antippen eines Punkts auf der Karte, mit dem Schieber oder mit dem Kompass des Handys;</li>\n  <li>die <strong>Rundzeiten</strong> mit der Stoppuhr (<span class=\"knopf\">Abflug</span> und <span class=\"knopf\">Zurück</span>), am besten drei bis fünf Runden. Aus der kürzesten Zeit schätzt die App die Entfernung zum Nest. Mit <span class=\"knopf\">+ Zeit</span> trägst du eine Zeit von Hand nach.</li>\n</ul>\n<p>Auf der Karte erscheint je Hornisse ein Flugkorridor. Mit Peilungen aus verschiedenen Richtungen grenzt die App einen <strong>Vermutungsbereich</strong> ein (rot, wo sich alle schneiden), mit Link zu Google Maps. <em>Karte drehen</em> richtet die Karte am Handy nach dem Kompass aus. Ist das Nest gefunden, setzt du den Fundort und schließt die Suche ab; abgeschlossene Suchen lassen sich archivieren und stehen dann nach Jahr im <em>Archiv</em>.</p>\n<figure><img src=\"/anleitung/bilder/nestsuche-peilung.webp\" loading=\"lazy\" alt=\"Nestsuche mit zwei Locktöpfen und Vermutungsbereich\"><figcaption>Zwei Locktöpfe mit je einer Peilung. Wo sich die Bereiche schneiden, liegt vermutlich das Nest (rotes Kreuz). Unter der Karte steht, wie groß der Bereich ist.</figcaption></figure>\n<figure><img src=\"/anleitung/bilder/nestsuche.webp\" loading=\"lazy\" alt=\"Nestsuche, Übersicht\"><figcaption>Nestsuche: neue Suche anlegen, darunter laufende Suchen und eine kurze Anleitung.</figcaption></figure>\n</section>\n\n<!-- 15 -->\n<section id=\"einstellungen\">\n<h2><span class=\"nr\">15</span>Einstellungen im Überblick</h2>\n<p>Die Einstellungen sind in vier Gruppen sortiert: <em>Betrieb</em>, <em>Ausstattung</em>, <em>Verbindungen</em> und (nur beim Inhaber) <em>Nur für dich</em>. Am Handy siehst du sie als Liste, jede Zeile zeigt kurz, wie es steht. Tippen öffnet den Punkt, <span class=\"knopf\">← Zurück</span> führt wieder zur Liste. Am PC und am iPad quer stehen alle Punkte links in einer Spalte, rechts der geöffnete Punkt.</p>\n<ul>\n  <li><strong>Bienenhalter:</strong> Name, Anschrift, Bundesland, Telefon, E-Mail, Registriernummer, für den Behandlungsnachweis und die Hornissen-Meldungen. Dazu <em>Name im Menü</em> (höchstens 30 Zeichen), leer steht dort „Imkereiverwaltung“.</li>\n  <li><strong>Bereiche:</strong> Schalter für Scannen, Königinnen (mit Zucht), Behandlungen, Dokumente, Lager und Velutina. Was du ausschaltest, verschwindet aus Menü und Seiten; die Daten bleiben und sind nach dem Einschalten wieder da. Bienenstände, Maßnahmen und Einstellungen sind immer an.</li>\n  <li><strong>Design:</strong> wie die App aussieht. <em>Wiese</em> hell in Grün und Honiggelb mit Seitenleiste, <em>Wald</em> warm in Waldgrün und Honig mit Leiste unten am Handy, <em>Bergsee</em> kühl in Petrol mit dunklem Band oben. Die Wahl gilt nur auf dem Gerät, auf dem du sie triffst. Hell und dunkel stellst du im Menü um.</li>\n  <li><strong>E-Mail-Versand:</strong> dein Postfach für den Versand von Dokumenten und Hornissen-Warnungen. <span class=\"knopf\">Speichern und Testmail senden</span> prüft die Angaben. Das <em>i</em> neben der Überschrift erklärt, welche Angaben Gmail, GMX, WEB.DE, T-Online, iCloud und Outlook brauchen (bei Gmail ein eigenes App-Passwort).</li>\n  <li><strong>Beutensysteme:</strong> Zargen für Bruträume und Honigräume, siehe <a href=\"#beispiel\">Erste Schritte</a>.</li>\n  <li><strong>Belegstellen:</strong> einmal anlegen (Ort, Rasse), dann bei Königinnen und Zuchtserien auswählbar. Weil die Drohnenvölker jedes Jahr wechseln, führt jede Belegstelle eine Liste <em>Drohnenvölker je Jahr</em>. Mit <span class=\"knopf\">Jahr eintragen</span> kommt ein Jahr dazu, aufgeklappt änderst oder entfernst du es. Die Liste zeigt auch, wie viele Königinnen je Jahr dort begattet wurden.</li>\n  <li><strong>Lager:</strong> je Erzeugnis die Sorten und Gebinde (Eimer, Gläser, Sonstige), bei Honig der Schalter „Eimer einzeln wiegen“ (echtes Gewicht je Eimer, z.&nbsp;B. für die Bio-Kontrolle). Ganz unten in der Karte steht der Schalter <em>Warenwert anzeigen</em> (Vorgabe aus, gilt für alle Erzeugnisse). Bei „an“ klappt darunter die Preisliste auf: <em>Standard</em> für Sorten ohne eigenen Preis, dazu je Sorte aufklappbar ein Preis je Stück für jedes Glas und ein Preis je kg für Eimer und lose Menge. Eimer rechnen immer je kg. Ganz unten die Lagerorte, nur nötig, wenn du an mehreren Orten lagerst.</li>\n  <li><strong>QR-Codes</strong> und <strong>Kalender-Abo</strong>, siehe oben.</li>\n  <li><strong>Helfer:</strong> Zugänge für Familie oder Mitimker, mit Lese- oder Schreibrecht, siehe <a href=\"#zugang\">Helfer einladen</a>.</li>\n  <li><strong>Historie:</strong> wer wann was angelegt oder geändert hat.</li>\n  <li><strong>System:</strong> Version der App, Update-Prüfung ein oder aus, <em>Was ist neu?</em> und <span class=\"knopf\">Update einspielen</span>.</li>\n</ul>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\" style=\"flex-basis:300px;max-width:440px\"><img src=\"/anleitung/bilder/einstellungen-bereiche.webp\" loading=\"lazy\" alt=\"Bereiche ein- und ausschalten\"><figcaption>Bereiche: Haken weg, dann verschwindet der Bereich aus dem Menü. Die Daten bleiben.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/einstellungen.webp\" loading=\"lazy\" alt=\"Einstellungen\"><figcaption>Bienenhalter in den Einstellungen. Links alle Punkte in vier Gruppen.</figcaption></figure>\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/belegstellen.webp\" loading=\"lazy\" alt=\"Belegstellen verwalten\"><figcaption>Belegstellen mit den Drohnenvölkern je Jahr.</figcaption></figure>\n</div>\n<div class=\"nebeneinander\">\n  <figure class=\"breit\"><img src=\"/anleitung/bilder/einstellungen-lager.webp\" loading=\"lazy\" alt=\"Einstellungen Lager\"><figcaption>Lager: Sorten, Gebinde, „Eimer einzeln wiegen“ und unten der Warenwert.</figcaption></figure>\n  <figure class=\"breit\" style=\"flex-basis:300px;max-width:520px\"><img src=\"/anleitung/bilder/einstellungen-preise.webp\" loading=\"lazy\" alt=\"Preisliste je Sorte\"><figcaption>Preisliste: Frühtracht aufgeklappt, je Glas ein Preis je Stück.</figcaption></figure>\n</div>\n</section>\n\n<!-- 16 -->\n<section id=\"fragen\">\n<h2><span class=\"nr\">16</span>Tipps und häufige Fragen</h2>\n<h3>Muss ich jede Durchsicht vollständig ausfüllen?</h3>\n<p>Nein. Trag ein, was du gesehen hast, alles andere bleibt leer. Eine Durchsicht mit nur einer Notiz ist völlig in Ordnung.</p>\n<h3>Ich habe alle Völker eines Stands gefüttert. Muss ich das für jedes Volk eintragen?</h3>\n<p>Nein. Nimm auf der Seite des Stands den Knopf <em>Durchsicht erfassen</em>, wähle <em>Alle wählen</em> und trag die Fütterung einmal ein. Jedes Volk bekommt seinen eigenen Eintrag (siehe <a href=\"#sammel\">Mehrere Völker auf einmal</a>).</p>\n<h3>Was bedeuten die Farben bei den Bewertungen?</h3>\n<p>Grün ist unauffällig, gelb verdient einen Blick, rot ist kritisch, etwa ein schwaches Volk, wenig Futter, starker Schwarmtrieb oder Varroa über der Schadschwelle. Es ist ein Hinweis, keine Pflichtaufgabe. Bei roten Werten bietet die App beim Speichern an, gleich eine Maßnahme anzulegen.</p>\n<h3>Ein Volk ist eingegangen. Löschen?</h3>\n<p>Besser den Status auf <em>verloren</em> setzen oder das Volk archivieren. So bleibt die Geschichte erhalten, etwa für den Behandlungsnachweis oder die Bewertung der Königin.</p>\n<h3>Die Königin wurde getauscht. Was tun?</h3>\n<p>Auf der Seite des Volks in der Königin-Zeile <span class=\"knopf\">Umweiseln</span> tippen. Dort wählst du die neue Königin und was mit der alten geschieht (abgedrückt, Reserve, verkauft, verschwunden). Beide Lebensläufe trägt die App ein (siehe <a href=\"#voelker\">Umweiseln</a>).</p>\n<h3>Funktioniert die App ohne Netz am Stand?</h3>\n<p>Durchsichten, neue Maßnahmen und Haken ja: Ohne Netz legt die App sie auf dem Handy ab und sendet sie von selbst, sobald wieder Verbindung da ist (siehe <a href=\"#funkloch\">Speichern ohne Netz</a>). Die App muss dafür aber schon offen sein. Neu laden lässt sie sich im Funkloch nicht.</p>\n<h3>Ich brauche die Zucht (oder das Lager) nicht.</h3>\n<p>Unter <em>Einstellungen → Bereiche</em> ausschalten. Menü und Seiten werden dadurch übersichtlicher, und du kannst den Bereich jederzeit wieder einschalten.</p>\n<h3>Ich habe etwas gefunden, das nicht funktioniert.</h3>\n<p>Melde es als <a href=\"https://github.com/frawoer79/Imkerei_Verwaltung/issues\">Issue auf GitHub</a>, am besten mit einem Screenshot und einer kurzen Beschreibung, was du gemacht hast. Im Testzugang sagst du einfach dem Betreiber Bescheid, der dich eingeladen hat.</p>\n<h3>Wie komme ich an neue Versionen?</h3>\n<p>Gibt es eine neue Version, zeigt die App dem Hauptzugang oben ein Band. Unter <em>Einstellungen → System</em> steht, was neu ist, und <span class=\"knopf\">Update einspielen</span> holt sie. Vorher sichert der Server die Datenbank, und klappt etwas nicht, geht er von selbst auf die alte Version zurück.</p>\n<p style=\"margin-top:28px\"><a class=\"zurueck\" href=\"#start\">↑ nach oben</a></p>\n</section>\n</div>\n</div>";
